{"path":"assets/css/styles.css","content":":root{
  --bg:#fbf7f2;
  --card:#fff6ef;
  --accent:#7a4b2a;
  --muted:#6b5b4a;
  --accent-2:#c98b5b;
  --glass: rgba(255,255,255,0.6);
  --radius:12px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--muted);line-height:1.45}
.wrap{max-width:1000px;margin:0 auto;padding:32px}
.site-header{background:linear-gradient(180deg,var(--card),var(--bg));border-bottom:1px solid rgba(122,75,42,0.06)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand .name{display:block;color:var(--accent);font-size:1.05rem}
.brand .tag{display:block;font-size:0.8rem;color:var(--accent-2)}
.main-nav{margin-left:auto;display:flex;gap:14px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.main-nav a:hover{background:rgba(122,75,42,0.06)}
.cta{margin-left:16px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none}
.hero{padding:56px 0;background-repeat:repeat;background-size:260px;color:var(--accent)}
.hero h1{font-size:2rem;margin:0 0 10px}
.lead{color:var(--muted);max-width:70ch}
.hero-actions{margin-top:18px;display:flex;gap:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;background:#fff;border:1px solid rgba(0,0,0,0.04);color:var(--muted);text-decoration:none;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border-color:transparent}
.btn.ghost{background:transparent;border:1px solid rgba(122,75,42,0.12)}
.btn.large{padding:14px 20px;font-size:1.05rem}
.social-proof{padding:28px 0}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
.card{background:var(--card);padding:14px;border-radius:10px;color:var(--muted);box-shadow:0 6px 18px rgba(0,0,0,0.04)}
.benefits{padding:28px 0}
.benefit-list{list-style:none;padding:0;margin:0 0 18px 0;display:grid;gap:10px}
.planner-block{background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));padding:14px;border-radius:12px;border:1px solid rgba(122,75,42,0.06)}
.session-planner label{display:block;font-weight:600;margin-top:10px;color:var(--accent)}
.session-planner select,.session-planner input{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:6px}
.notes-checks{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.notes-checks label{background:#fff;padding:6px 8px;border-radius:8px;border:1px solid rgba(0,0,0,0.04);font-size:0.9rem}
.planner-actions{display:flex;gap:8px;margin-top:12px}
.sp-output{width:100%;padding:10px;border-radius:8px;border:1px dashed rgba(0,0,0,0.06);background-color:#fff;margin-top:8px}
.process{padding:28px 0}
.steps{counter-reset:step;list-style:none;padding:0}
.steps li{position:relative;padding-left:52px;margin-bottom:14px}
.steps li:before{content:counter(step);counter-increment:step;position:absolute;left:0;top:0;background:var(--accent-2);color:#fff;width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-weight:700}
.faq{padding:28px 0}
.qa h3{margin-top:12px;color:var(--accent)}
.callout{padding:36px 0;background:linear-gradient(180deg,rgba(201,139,91,0.06),transparent)}
.site-footer{padding:18px 0;border-top:1px solid rgba(122,75,42,0.04)}
.contact a{color:var(--accent)}

/* Reveal animation */
[data-reveal]{opacity:0;transform:translateY(18px);transition:opacity 420ms cubic-bezier(.2,.9,.3,1),transform 420ms cubic-bezier(.2,.9,.3,1)}
[data-reveal].visible{opacity:1;transform:none}

/* Reduced motion */
@media (prefers-reduced-motion: reduce){
  [data-reveal]{transition:none;opacity:1;transform:none}
}

/* Responsive */
@media (max-width:700px){
  .wrap{padding:18px}
  .main-nav{display:none}
  .hero h1{font-size:1.4rem}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utility: set current year
  document.addEventListener('DOMContentLoaded',function(){
    var y = document.getElementById('year'); if(y) y.textContent = new Date().getFullYear();
  });

  // Scroll reveal respecting prefers-reduced-motion
  function initReveal(){
    var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var items = document.querySelectorAll('[data-reveal]');
    if(prefersReduced){
      items.forEach(function(it){ it.classList.add('visible'); });
      return;
    }
    if('IntersectionObserver' in window){
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      items.forEach(function(it){ obs.observe(it); });
    } else {
      // fallback: reveal on load
      items.forEach(function(it){ it.classList.add('visible'); });
    }
  }
  initReveal();

  // Session Planner: works for multiple instances
  function buildPlanner(container){
    var goal = container.querySelector('.sp-goal');
    var length = container.querySelector('.sp-length');
    var sens = container.querySelector('.sp-sens');
    var checks = Array.from(container.querySelectorAll('.notes-checks input[type=checkbox]'));
    var output = container.querySelector('.sp-output');

    function gather(){
      var chosen = checks.filter(function(c){ return c.checked; }).map(function(c){ return c.value; }).slice(0,3);
      var minutes = parseInt(length.value,10)||10;
      var g = goal.value||'calm';
      var sensText = (sens.value||'none provided').trim();
      // Simple dilution logic: shorter session -> smaller total volume
      var totalCarrier = minutes <= 10 ? 5 : (minutes <= 20 ? 10 : 15); // ml
      // Drop suggestion: 1% = ~6 drops per 10ml; we'll approximate
      var percent = minutes <= 10 ? 1 : (minutes <= 20 ? 1.5 : 2);
      var dropsPer10ml = 6;
      var drops = Math.round((percent/1)*dropsPer10ml*(totalCarrier/10));
      if(drops < 1) drops = 1;

      var notesLine = chosen.length ? chosen.join(', ') : 'no specific notes chosen';

      var summary = [];
      summary.push('Session planner summary');
      summary.push('-----------------------');
      summary.push('Focus: ' + g);
      summary.push('Length: ' + minutes + ' minutes');
      summary.push('Preferred notes: ' + notesLine);
      summary.push('Sensitivity info: ' + sensText);
      summary.push('');
      summary.push('Suggested blend (for topical use or diffuser carrier):');
      summary.push('- Carrier: ' + totalCarrier + ' ml');
      summary.push('- Essential oil drops: ~' + drops + ' drops total');
      summary.push('- Approx. dilution: ' + percent.toFixed(1) + '%');
      summary.push('');
      summary.push('Safety reminders:');
      summary.push('- Perform a patch test for topical use (apply 1 drop diluted, observe 24h).');
      summary.push('- If you have pets, pregnancy, or medical conditions, consult intake guidance before use.');
      summary.push('- These suggestions may support comfort; they are not medical treatment.');

      return summary.join('\n');
    }

    function update(){ output.value = gather(); }

    // Actions
    container.addEventListener('click',function(e){
      var btn = e.target.closest('button'); if(!btn) return;
      var action = btn.getAttribute('data-action');
      if(action === 'build'){ update(); }
      if(action === 'clear'){
        goal.selectedIndex = 0; length.selectedIndex = 0; sens.value=''; checks.forEach(function(c){ c.checked=false }); output.value='';
      }
      if(action === 'copy'){
        // copy output to clipboard
        try{
          navigator.clipboard.writeText(output.value).then(function(){
            btn.textContent = 'Copied'; setTimeout(function(){ btn.textContent='Copy summary'; },1400);
          }, function(){ fallbackCopy(output.value,btn); });
        }catch(err){ fallbackCopy(output.value,btn); }
      }
    });

    // fallback copy
    function fallbackCopy(text,btn){
      var ta = document.createElement('textarea'); ta.value=text; document.body.appendChild(ta); ta.select();
      try{ document.execCommand('copy'); btn.textContent='Copied'; setTimeout(function(){ btn.textContent='Copy summary'; },1400); }catch(e){}
      document.body.removeChild(ta);
    }

  }

  // Initialize planners
  document.addEventListener('DOMContentLoaded', function(){
    var planners = document.querySelectorAll('.session-planner');
    planners.forEach(function(p){ buildPlanner(p); });
  });

})();"} 
